wpcloud/graph.css:
& {
	padding: 1em;
	box-sizing: border-box;
	margin-bottom: 0 !important;

	/* Horizontal Bar Graph Styles */
}

& .uplot {
	width: 100%;
}

& .uplot .u-wrap {
	width: 100%;
}

& .u-title {
	padding-bottom: 10px;
	margin: 0;
	text-align: left;
	font-size: 18px;
	font-weight: bold;
	color: var(--pico-color);
}

& .wpcloud-horizontal-bar-graph-title {
	padding-bottom: 10px;
	margin: 0;
	text-align: left;
	font-size: 18px;
	font-weight: bold;
	color: var(--pico-color);
}

& .u-legend {

	/* Allow the legend to grow and not be clipped */ /* Reduce bottom space */ /* Reduce bottom space */
}

& .u-legend .u-marker {
	height: .25em !important;
	border-radius: 0.125em;
}

& .u-legend .u-label {
	text-overflow: ellipsis;
	width: 80px;
	white-space: nowrap;
	overflow: hidden;
}

& .u-legend {
	max-height: none !important;
	overflow: visible !important;
	margin-bottom: 0 !important;
	padding-bottom: 0 !important;
}

	/* Style legend table */

& .u-legend table {
	width: 100%;
	margin-bottom: 0; /* Reduce bottom space */
}

	/* When many series, allow wrapping to multiple columns */

& .u-legend.u-legend-many {
	display: flex;
	flex-wrap: wrap;
}

& .u-legend.u-legend-many tr {
	width: auto;
	min-width: 150px;
	margin-right: 10px;
}

& .u-series th {
	background: none;
}

& .u-series td {
	background: none;
}

& .wpcloud-horizontal-bar-graph {
	display: flex;
	flex-direction: column;
	width: 100%;
	padding: 20px;
	box-sizing: border-box;
}

& .wpcloud-horizontal-bar-graph-container {
	display: flex;
	flex-direction: column;
	width: 100%;
	gap: 8px;
	box-sizing: border-box;
}

& .wpcloud-horizontal-bar-graph-row {
	display: grid;
	grid-template-columns: minmax(150px, 25%) 1fr 70px;
	align-items: center;
	gap: 10px;
	width: 100%;
	height: 30px;
}

& .wpcloud-horizontal-bar-graph-label {
	font-size: 0.9rem;
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
	padding-left: 5px;
}

& .wpcloud-horizontal-bar-graph-bar-container {
	height: 20px;
	background-color: rgba(0, 0, 0, 0.3);
	border-radius: 2px;
	overflow: hidden;
}

& .wpcloud-horizontal-bar-graph-bar {
	height: 100%;
	border-radius: 2px;
	transition: width 0.3s ease;
}

& .wpcloud-horizontal-bar-graph-value {
	font-size: 0.9rem;
	font-weight: 600;
	text-align: right;
	padding-right: 5px;
}

	@media (prefers-color-scheme: dark) {
& {
	border-radius: var(--pico-border-radius);
	border: var(--pico-border-width) solid var(--pico-form-element-border-color);
	background-color: var(--pico-form-element-background-color);
	color: var(--pico-form-element-placeholder-color);
}

& .wpcloud-horizontal-bar-graph-bar-container {
	background-color: rgba(255, 255, 255, 0.1);
}
}
